const responses = $input.all().map(item => item.json);

// Filter to last 7 days
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
const recentResponses = responses.filter(r => {
  const date = new Date(r.submitted_at || r.timestamp);
  return date >= oneWeekAgo;
});

const total = recentResponses.length;
if (total === 0) {
  return [{ json: { total: 0, error: 'No responses this week' } }];
}

// NPS Calculation (0-10 scale)
const npsScores = recentResponses
  .map(r => parseInt(r.nps_score || r.recommendation_score || 0))
  .filter(s => !isNaN(s));

const promoters = npsScores.filter(s => s >= 9).length;
const detractors = npsScores.filter(s => s <= 6).length;
const nps = npsScores.length > 0 
  ? Math.round(((promoters - detractors) / npsScores.length) * 100) 
  : null;

// CSAT Calculation (1-5 scale)
const csatScores = recentResponses
  .map(r => parseInt(r.satisfaction_score || r.csat || 0))
  .filter(s => !isNaN(s) && s > 0);

const csatAvg = csatScores.length > 0
  ? (csatScores.reduce((a, b) => a + b, 0) / csatScores.length).toFixed(2)
  : null;

const satisfied = csatScores.filter(s => s >= 4).length;
const csatPercent = csatScores.length > 0
  ? Math.round((satisfied / csatScores.length) * 100)
  : null;

// Category breakdown
const categories = {};
recentResponses.forEach(r => {
  const cat = r.category || 'Uncategorized';
  categories[cat] = (categories[cat] || 0) + 1;
});

// Score distribution for charts
const npsDistribution = { '0-6': 0, '7-8': 0, '9-10': 0 };
npsScores.forEach(s => {
  if (s <= 6) npsDistribution['0-6']++;
  else if (s <= 8) npsDistribution['7-8']++;
  else npsDistribution['9-10']++;
});

return [{
  json: {
    report_date: new Date().toISOString().split('T')[0],
    period: `${oneWeekAgo.toISOString().split('T')[0]} to ${new Date().toISOString().split('T')[0]}`,
    total_responses: total,
    nps_score: nps,
    nps_promoters: promoters,
    nps_passives: npsScores.length - promoters - detractors,
    nps_detractors: detractors,
    nps_distribution: npsDistribution,
    csat_average: csatAvg,
    csat_percentage: csatPercent,
    csat_total_rated: csatScores.length,
    category_breakdown: categories,
    chart_data: {
      nps: npsDistribution,
      categories: categories
    }
  }
}];

const data = $input.first().json;

const npsEmoji = data.nps_score >= 50 ? '🟢' : data.nps_score >= 0 ? '🟡' : '🔴';
const csatEmoji = data.csat_percentage >= 80 ? '🟢' : data.csat_percentage >= 60 ? '🟡' : '🔴';

let categoryTable = 'Category | Count\n---|---\n';
for (const [cat, count] of Object.entries(data.category_breakdown || {})) {
  categoryTable += `${cat} | ${count}\n`;
}

const report = `
📊 WEEKLY SURVEY REPORT
========================
Period: ${data.period}
Total Responses: ${data.total_responses}

--- NPS SCORE ---
${npsEmoji} NPS: ${data.nps_score}
  Promoters (9-10): ${data.nps_promoters}
  Passives  (7-8):  ${data.nps_passives}
  Detractors (0-6): ${data.nps_detractors}

--- CSAT SCORE ---
${csatEmoji} Average: ${data.csat_average}/5.0
  Satisfaction Rate: ${data.csat_percentage}%
  Total Rated: ${data.csat_total_rated}

--- CATEGORY BREAKDOWN ---
${categoryTable}

--- CHART DATA (JSON) ---
${JSON.stringify(data.chart_data, null, 2)}
`;

return [{ json: { ...data, formatted_report: report } }];
